// ==================================================================
// FAST-PATH INTENT EXTRACTION & REGEX TRIAGE ENGINE
// Zero-latency regex pattern matching for explicit human handoff
// ==================================================================

const raw = $input.first().json;
const payload = raw.body || raw;

const message = (payload.message || payload.text || payload.Body || payload.content || '').toString().trim();
const customerName = (payload.customerName || payload.name || payload.ProfileName || 'Customer').toString().trim();
const customerPhone = (payload.phone || payload.from || payload.From || payload.sender || 'Unknown').toString().trim();
const conversationId = (payload.conversationId || payload.chatId || payload.id || `conv_${Date.now()}`).toString();

const humanIntentPatterns = [
  /خدم[ةه]\s*العملا[ءإ]/,
  /عنصر\s*بشر[يى]/,
  /موظف/,
  /بشر[يى]/,
  /إنسان|انسان/,
  /شخص\s*(حقيقي)?/,
  /آدمي|ادمي/,
  /حولن[يى]/,
  /أبغ[يى]\s*(أ)?كلم/,
  /ابغ[يى]\s*(ا)?كلم/,
  /عايز\s*(أ)?كلم/,
  /عاوز\s*(أ)?كلم/,
  /بدي\s*احك[يى]/,
  /تحدث\s*مع/,
  /محادث[ةه]\s*بشر/,
  /اتصال\s*بشر/,
  /كلمني\s*حد/,
  /ابي\s*احد/,
  /مسؤول/,
  /مدير/,
  /\bhuman\b/i,
  /\bagent\b/i,
  /\brepresentative\b/i,
  /\bsupport\s*team\b/i,
  /\breal\s*person\b/i,
  /\blive\s*agent\b/i
];

const humanRequested = humanIntentPatterns.some(pattern => pattern.test(message));

return [{
  json: {
    message,
    customerName,
    customerPhone,
    conversationId,
    humanRequested,
    timestamp: new Date().toISOString()
  }
}];

// ==================================================================
// HUMAN HANDOFF DISPATCH TRANSFORMER
// Halts AI loop, crafts client acknowledgement, formats internal alert
// ==================================================================

const data = $input.first().json;

const customerReply = `أهلاً بك ${data.customerName} 👋\n\nتم تحويل محادثتك لفريق خدمة العملاء، وسيقوم أحد ممثلينا بالتواصل معك والرد عليك في أقرب وقت.\n\nشكراً لصبرك معنا 🙏`;

const internalAlert = `ALERT: Human Representative Requested\nPriority: HIGH\nCustomer: ${data.customerName}\nIdentifier: ${data.customerPhone}\nMessage: "${data.message}"\nTimestamp: ${data.timestamp}\nDirective: Assign dedicated agent to active conversation thread.`;

return [{
  json: {
    ...data,
    action: 'human_handoff',
    aiExecutionHalted: true,
    replyToCustomer: customerReply,
    internalAlert: internalAlert,
    supervisorSentiment: 'neutral'
  }
}];

