// ==================================================================
// RISK SCORING & POLICY EVALUATION ENGINE
// Evaluates confidence thresholds and enforces escalation policies
// ==================================================================

const prev = $('Fast-Path Intent Evaluator').first().json;
const supervisorResponse = $input.first().json;

let metrics = {
  sentiment: 'neutral',
  shouldEscalate: false,
  escalationReason: null,
  purchaseIntent: 'none',
  suggestedAction: 'Standard Automated Synthesis',
  suggestedInternalNote: null,
  confidenceScore: 0.85
};

try {
  const rawContent = supervisorResponse.choices?.[0]?.message?.content || '{}';
  metrics = { ...metrics, ...JSON.parse(rawContent) };
} catch (e) {
  // Safe fallback
}

const isHostile = metrics.sentiment === 'angry';
const escalationPolicyTriggered = (
  metrics.confidenceScore >= 0.70 &&
  (metrics.shouldEscalate === true || isHostile)
);

return [{
  json: {
    ...prev,
    supervisor: metrics,
    escalationPolicyTriggered
  }
}];

// ==================================================================
// INCIDENT ESCALATION PAYLOAD BUILDER
// Prepares empathetic client soothing copy and isolated staff dossier
// ==================================================================

const data = $input.first().json;
const sv = data.supervisor;

const clientDeescalationReply = `أهلاً بك ${data.customerName} 🙏\n\nنتفهم تماماً استياءك ونأسف لأي تجربة غير مرضية. تم تصعيد محادثتك فوراً للإدارة وفريق خدمة العملاء المتخصص للتدخل ومعالجة الأمر على الفور.\n\nنقدّر صبرك معنا.`;

const staffIncidentDossier = `CRITICAL INCIDENT ALERT: High Friction Customer Encounter\nSeverity: CRITICAL\nSentiment Vector: ${sv.sentiment.toUpperCase()}\nEscalation Cause: ${sv.escalationReason || 'Severe Customer Dissatisfaction'}\nOperational Recommendation: ${sv.suggestedAction}\nConfidence Level: ${(sv.confidenceScore * 100).toFixed(0)}%\nCustomer: ${data.customerName} (${data.customerPhone})\nTranscript: "${data.message}"\nTimestamp: ${data.timestamp}`;

return [{
  json: {
    ...data,
    action: 'escalation_protocol',
    aiExecutionHalted: true,
    replyToCustomer: clientDeescalationReply,
    internalAlert: staffIncidentDossier
  }
}];

