// ==================================================================
// P0 ZERO-LEAKAGE SECURITY GUARDRAIL
// Intercepts and sanitizes LLM output to prevent internal note contamination
// ==================================================================

const prev = $('Escalation Policy Router').first().json;
const synthesisResponse = $input.first().json;

let responseText = 'أهلاً بك! شكراً لتواصلك معنا، كيف يمكننا مساعدتك اليوم؟';

try {
  responseText = synthesisResponse.choices?.[0]?.message?.content || responseText;
} catch (e) {}

const leakageSignatures = [
  /AI Supervisor/i,
  /تنبيه تصعيد/,
  /ملاحظة داخلية/,
  /التوجيه للموظف/,
  /internal note/i,
  /incident alert/i,
  /severity/i,
  /🚨/,
  /شعور العميل/,
  /سبب التصعيد/
];

const containsLeakage = leakageSignatures.some(sig => sig.test(responseText));

if (containsLeakage) {
  responseText = `أهلاً بك ${prev.customerName} 👋\nشكراً لتواصلك معنا! تم استلام استفسارك وسيتم الرد عليك في أقرب وقت من قبل فريقنا المتخصص.`;
}

let leadNotification = null;
if (prev.supervisor?.purchaseIntent === 'high_intent') {
  leadNotification = `HIGH-INTENT COMMERCIAL OPPORTUNITY\nProspect: ${prev.customerName} (${prev.customerPhone})\nIntent Signal: Ready to Buy / Engage\nMessage Context: "${prev.message}"\nRecommended Action: Prioritize commercial follow-up.`;
}

return [{
  json: {
    ...prev,
    action: 'automated_synthesis',
    aiExecutionHalted: false,
    replyToCustomer: responseText,
    internalAlert: leadNotification
  }
}];
